INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40027, 0, 0, 0, 0, 0, 0, 0, 0, 'The Sanv Charm means a lot to me, outsider. The Sanv were once a large tribe in Outlands. Sadly, I am the only that remains. Let me prepare the communication with the lost one.', 0),
(40028, 0, 0, 0, 0, 0, 0, 0, 0, 'You\'ve done it! This is the horn. I must thank you greatly. Without you, it would have been lost forever. Words alone cannot express how pleased I am to have this once more.$B$BPlease, take my ring as a symbol of my gratitude and respect.', 0),
(40029, 0, 0, 0, 0, 0, 0, 0, 0, 'It saddens me that we must slay our brethren, of those we shared so much hope in coming to this world. But their minds are warped. They are no longer friends. You have freed their souls, outsider. Thank you.', 0),
(40030, 0, 0, 0, 0, 0, 0, 0, 0, 'You have done it? Have you truly defeated the terrible one? This is a joyous day for the Harborage. He was a direct threat to our survival, and we did not have the strength to face him.$B$BWe are fortunate you could help, outsider! Please, as a symbol of our gratitude, take one of our artifacts from the old world. They serve no purpose to us anymore. We must look to the future and not remember the brutal past.', 0),
(40031, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, more leather to work with. My hands are eager to get started. I thank you, outsider, for  getting me this.', 0),
(40032, 0, 0, 0, 0, 0, 0, 0, 0, 'We shall begin the communication at once. Stand back, outsider. Our magic is unstable.', 0),
(40033, 0, 0, 0, 0, 0, 0, 0, 0, 'Sanv K\'la sent you? I am happy to hear his name once more. I thought I would never hear from him again, nor would I think he would send someone so far to seek me.', 0),
(40071, 0, 0, 0, 0, 0, 0, 0, 0, 'Thanks for delivering this report. I trust Biggs can manage to get here. The Draenei of the region have become a problem that need to be dealt with.', 0),
(40072, 0, 0, 0, 0, 0, 0, 0, 0, 'I cannot describe how pleased I am. I had generations looking down upon me with anger before, and I feel peaceful. Maybe I can return to Stormwind soon. Thanks again.', 0),
(40073, 0, 0, 0, 0, 0, 0, 0, 0, 'I cannot thank you enough. This will mean a lot in the long term, and I will put it to good use, I assure you.', 0),
(40074, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, you come from Sorrowguard? It\'s been about a month since I last heard from them. I assumed the worst.', 0),
(40075, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank the heavens. I have been worried about this order since the trouble with shipping weeks ago. At the least, we have a stock of swords available should anything bad happen, and it has freed up my iron for other things.$B$BHere. Take one as a way for me to pay you for your services.', 0),
(40076, 0, 0, 0, 0, 0, 0, 0, 0, 'These are quite heavy pieces of meat. They will last me a while if I ration everything out. Thanks again. You\'ve kept us fed.', 0),
(40077, 0, 0, 0, 0, 0, 0, 0, 0, 'Huha! you did it, partner. Now I can finally make some coin and sell some of these off, but here. Don\'t say I didn\'t cut you in on the profits!', 0),
(40078, 0, 0, 0, 0, 0, 0, 0, 0, 'Well done. We are one step closer to salvation. The murlocs have been a thorn in our side for too long.', 0),
(40079, 0, 0, 0, 0, 0, 0, 0, 0, 'You have done good work. For a while longer, we can remain undetected within the mountains and hopefully keep the eyes of the Horde off of us.', 0),
(40095, 0, 0, 0, 0, 0, 0, 0, 0, 'This... This is it. You found it. I must say, looking at this again, after all these years, is quite something.', 0),
(40206, 0, 0, 0, 0, 0, 0, 0, 0, 'Ahh, such fine specimens these are, I will make haste at once to prepare it for the camp, and save some extra for my tinkering purposes. Thanks again for all of the work out there, I can imagine you got pestered by aggresive wildlife in your searching.', 0),
(40207, 0, 0, 0, 0, 0, 0, 0, 0, 'Potent, extremely potent, it would appear that the deathstrike tarantulas have been growing more strong over the past months. I will still attempt what I can, thank you again $N, perhaps I can best such a venom one day.', 0),
(40208, 0, 0, 0, 0, 0, 0, 0, 0, 'Such a rarity this is, many in Orgrimmar wouldn\'t even have the opportunity to have something as powerful as this could potentially be! I must thank you, and thank you again, I will make good use of this.', 0),
(40209, 0, 0, 0, 0, 0, 0, 0, 0, 'I never imagined the day would come so soon, Sorrowclaw always was able to elude my efforts.$B$BYou are a much greater then myself, please, be rewarded for your glory of defeating such a beast!', 0),
(40231, 0, 0, 0, 0, 0, 0, 0, 0, 'Watch Paladin Janathos sent you, well I know the man well. He spoke with me before his departure out to Sorrowguard. It is good to hear that he is alive. If he desires me to keep this book within the Cathedral I will do as such, perhaps the words written inside will benefit those of the faith.', 0),
(40232, 0, 0, 0, 0, 0, 0, 0, 0, 'So, then it is done? The Archbishop has always been a friend of mine, his convictions and word in the light has always been true.$B$BThis scroll will continue to guide our actions here, and keep us safe within Sorrowguard.', 0),
(40233, 0, 0, 0, 0, 0, 0, 0, 0, '<A smile would crest across Janathos\' face as he looks upon the orb>. My mentor would be proud of us to recover such an item. You truly are blessed of the light for your services here in this dark corner of Azeroth.$B$BPlease, take this as a token of my appreciation, and walk with swiftness upon this earth, as blessed by the light.', 0),
(41117, 0, 0, 0, 0, 0, 0, 0, 0, 'The magic flowing from this tablet is intense! I would never have expected such energy from the trolls.$B$BYou have done me a solid favor, and for your help I offer you this tome. It should give you the knowledge to teleport to Stonard. May my magic serve you well!', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40027, 0, 0, 'The Sanv Charm must be recovered, outsider. Be quick.', 0),
(40028, 0, 0, 'Have you gotten my prized possession, outsider?', 0),
(40029, 0, 0, 'Has it been done yet, outsider?', 0),
(40030, 0, 0, 'Has the feared one been defeated?', 0),
(40031, 0, 0, 'Have you procured the leather?', 0),
(40032, 0, 0, 'We must attempt to find Akh Z\'ador, and quickly outsider.', 0),
(40033, 0, 0, 'I come from a far away land, and I seek no hostility. What is it you need?', 0),
(40071, 0, 0, 'Yes, may I assist?', 0),
(40072, 0, 0, 'I don\'t want to lose my father\'s legacy. Have you had any luck?', 0),
(40073, 0, 0, 'Have you gotten them? The iron supplies I have will not last forever.', 0),
(40074, 0, 0, 'Welcome to our blacksmithing shop. Can I help you?', 0),
(40075, 0, 0, 'You return with good news, I hope?', 0),
(40076, 0, 0, 'Have you had any luck?', 0),
(40077, 0, 0, 'Any luck? The swamp is a dangerous place, so be careful!', 0),
(40078, 0, 0, 'The murlocs, are they dealt with?', 0),
(40079, 0, 0, 'Has it been done? Have you kept our secrecy here?', 0),
(40095, 0, 0, 'I take it you have had no luck?', 0),
(40206, 0, 0, 'You must search the entirety of the swamp, Sorrowmoss can grow almost anywhere!', 0),
(40207, 0, 0, 'Deathstrike Venom can be fatal if used improperly, be careful in handling it!', 0),
(40208, 0, 0, 'The power of the Green Dragonflight is not something to be underestimated, be careful in getting that scale!', 0),
(40209, 0, 0, 'Sorrowclaw is a dangerous beast, be careful within the swamp.', 0),
(40231, 0, 0, 'How may I assist you?', 0),
(40232, 0, 0, 'Have you spoken with Benedictus?', 0),
(40233, 0, 0, 'The Orb of Kaladus holds great power in the light. My mentors artifact should not be wielded by zealots.', 0),
(41117, 0, 0, 'Have you found this mysterious Kazkaz yet?', 0);
