INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(60421, 0, 0, 'You have saved Harborage!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67022'),
(60422, 0, 0, 'Noboru is dead? We thank you outsider!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67023'),
(60423, 0, 0, 'We will fear no longer the menace Noboru.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67024'),
(60424, 0, 0, 'Our journey here was not pointless after all, thank you.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 67025');
